<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('programme_officer');$user=current_user();$flashes=render_flashes();$currentPage='activity_log';$pageTitle='Activity Log';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$officerId=(int)($user['id']??$user['user_id']??0);if($officerId<=0){http_response_code(403);exit('Invalid Programme Officer account.');}$exists=po_activity_table_exists($conn);$rows=[];if($exists){$stmt=$conn->prepare("SELECT id,action,description,entity_type,entity_id,ip_address,created_at FROM programme_officer_activity_log WHERE programme_officer_id=? ORDER BY created_at DESC,id DESC LIMIT 100");$stmt->bind_param('i',$officerId);$stmt->execute();$r=$stmt->get_result();while($row=$r->fetch_assoc())$rows[]=$row;$stmt->close();}require __DIR__.'/_layout_start.php';?>
<div class="po-page-header"><div><span class="po-page-header__eyebrow">Audit & Accountability</span><h2>Activity Log</h2><p>A transparent record of Programme Officer actions captured by the platform.</p></div></div><?php if(!$exists):?><div class="po-alert"><i class="fas fa-database"></i><div><strong>Activity log table is not installed yet.</strong><span>Import programme_officer_portal.sql from this package. This page fails safely instead of producing a database fatal error.</span></div></div><?php endif;?>
<div class="po-card"><div class="po-card__header"><div><h3>Recent Activity</h3><p>Latest 100 recorded actions.</p></div></div><?php if(!$rows):?><div class="po-empty"><div class="po-empty__icon"><i class="fas fa-clock-rotate-left"></i></div><strong>No activity recorded</strong><span>Recorded Programme Officer actions will appear here.</span></div><?php else:?><div class="po-activity-list"><?php foreach($rows as $r):?><article class="po-activity"><div class="po-activity__icon"><i class="fas fa-bolt"></i></div><div class="po-activity__body"><div class="po-activity__title"><strong><?= e(po_status_label($r['action'])) ?></strong><span><?= e(po_datetime($r['created_at'])) ?></span></div><p><?= e($r['description']) ?></p><div class="po-activity__meta"><?php if(!empty($r['entity_type'])):?><span><i class="fas fa-tag"></i> <?= e(po_status_label($r['entity_type'])) ?><?= $r['entity_id']?' #'.(int)$r['entity_id']:'' ?></span><?php endif;?><?php if(!empty($r['ip_address'])):?><span><i class="fas fa-globe"></i> <?= e($r['ip_address']) ?></span><?php endif;?></div></div></article><?php endforeach;?></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php';?>
